begin;
select plan(8);
select ok(not has_function_privilege('authenticated','public.resolve_books_project_owner_request(uuid,uuid,uuid,uuid,uuid,text,jsonb,text)','execute'),'project owner resolution stays private');
select ok(not has_function_privilege('anon','public.resolve_books_project_owner_request(uuid,uuid,uuid,uuid,uuid,text,jsonb,text)','execute'),'anonymous cannot resolve ownership');
select ok(has_function_privilege('service_role','public.resolve_books_project_owner_request(uuid,uuid,uuid,uuid,uuid,text,jsonb,text)','execute'),'authorized server can resolve scoped ownership requests');
select ok(not (select prosecdef from pg_proc where oid='public.resolve_books_project_owner_request(uuid,uuid,uuid,uuid,uuid,text,jsonb,text)'::regprocedure),'resolution preserves invoker authority');
select ok(not has_table_privilege('authenticated','public.books_project_owner_request_resolutions','insert'),'authenticated cannot cancel ownership directly');
select ok(not has_table_privilege('anon','public.books_project_owner_request_fences','update'),'anonymous cannot rewrite request coordination');
select ok((select relrowsecurity from pg_class where oid='public.books_project_owner_request_resolutions'::regclass),'cancellation history uses RLS defense');
select ok((select relrowsecurity from pg_class where oid='public.books_project_owner_request_fences'::regclass),'operational fences use RLS defense');
select * from finish();
rollback;
